// Drizzle table definitions (sqliteTable from drizzle-orm/sqlite-core).
// After changing them, run `pnpm db:generate` to write a migration.
//
// The auth tables are generated by better-auth (`pnpm auth:generate`); don't
// edit auth-schema.ts by hand.
import { sql } from 'drizzle-orm';
import { index, integer, real, snakeCase, text, uniqueIndex } from 'drizzle-orm/sqlite-core';

import { coordinateStatuses, placeKinds } from '../../lib/place-kinds';
import { baptismLocations, recordKinds, recordStatuses, sexes } from '../../lib/record-kinds';
import { user } from './auth-schema';

export * from './auth-schema';

// Genealogy data has three layers:
//   source → record   what a register or list says, kept word for word (`raw`);
//   persona           a person as mentioned in one record, in one role, with
//                     the name and attributes parsed from it;
//   person            a researched identity that personas are linked to.
//
// Dates are reduced-precision ISO 8601 text ('1895', '1895-03', '1895-03-12'):
// it sorts as text and keeps how much the source actually says. The original
// wording stays in `raw` and the `*Text` columns.
//
// Columns named `*Text` hold a value exactly as written; the matching `*Id`
// column is what an admin resolved it to (a place, a term, a clergyman).

const now = sql`(cast(unixepoch('subsecond') * 1000 as integer))`;

// Who created and last changed a row. Admins edit by hand; `version` lets a
// save check that nobody else changed the row since it was loaded.
const audit = () => ({
  createdAt: integer({ mode: 'timestamp_ms' }).default(now).notNull(),
  createdBy: text().references(() => user.id, { onDelete: 'set null' }),
  updatedAt: integer({ mode: 'timestamp_ms' })
    .default(now)
    .$onUpdate(() => new Date())
    .notNull(),
  updatedBy: text().references(() => user.id, { onDelete: 'set null' }),
  version: integer().default(1).notNull(),
});

// --- Places -----------------------------------------------------------------

export const parish = snakeCase.table('parish', {
  id: integer().primaryKey(),
  nameRu: text().notNull(),
  nameFi: text(),
  note: text(),
  ...audit(),
});

export { coordinateStatuses, placeKinds };

// A canonical place. Spellings found in sources are `placeAlias` rows.
export const place = snakeCase.table(
  'place',
  {
    id: integer().primaryKey(),
    kind: text({ enum: placeKinds }).default('village').notNull(),
    nameRu: text().notNull(),
    nameFi: text(),
    parishId: integer().references(() => parish.id, { onDelete: 'set null' }),
    latitude: real(),
    longitude: real(),
    coordinateStatus: text({ enum: coordinateStatuses }).default('unknown').notNull(),
    note: text(),
    ...audit(),
  },
  (t) => [index('place_parish_idx').on(t.parishId), index('place_name_ru_idx').on(t.nameRu)],
);

// A spelling of a place as written in a source ("Нисковицы", "Горки\n(Молосковицы)").
// The entry grid offers these when an admin types a place.
export const placeAlias = snakeCase.table(
  'place_alias',
  {
    id: integer().primaryKey(),
    placeId: integer()
      .notNull()
      .references(() => place.id, { onDelete: 'cascade' }),
    name: text().notNull(),
  },
  (t) => [
    uniqueIndex('place_alias_place_name_idx').on(t.placeId, t.name),
    index('place_alias_name_idx').on(t.name),
  ],
);

// --- Vocabularies -------------------------------------------------------------

export const termVocabularies = [
  'relation', // household or taxpayer role: отец, сын, bonde, dräng…
  'rank', // звание: крестьянин, мещанин, торпарь…
  'civil_status', // женат, вдова, холост…
  'death_cause',
] as const;

// A recurring value, translated once for the app's locales. Personas keep the
// wording of their source in `*Text`; the term is what it was resolved to.
export const term = snakeCase.table(
  'term',
  {
    id: integer().primaryKey(),
    vocabulary: text({ enum: termVocabularies }).notNull(),
    ru: text().notNull(),
    fi: text(),
    en: text(),
    note: text(),
    ...audit(),
  },
  (t) => [uniqueIndex('term_vocabulary_ru_idx').on(t.vocabulary, t.ru)],
);

// Pastors, vicars and sextons (кистер) who baptised, married or buried.
export const clergy = snakeCase.table('clergy', {
  id: integer().primaryKey(),
  nameRu: text().notNull(),
  nameFi: text(),
  note: text(),
  ...audit(),
});

// --- Sources and records --------------------------------------------------------

export const sourceKinds = recordKinds;

// A register or list: one book, or one archival file.
export const source = snakeCase.table(
  'source',
  {
    id: integer().primaryKey(),
    kind: text({ enum: sourceKinds }).notNull(),
    parishId: integer().references(() => parish.id, { onDelete: 'set null' }),
    title: text().notNull(),
    archiveReference: text(), // e.g. fond / opis / delo
    yearFrom: integer(),
    yearTo: integer(),
    language: text(), // language of the original: ru, fi, sv, de, et…
    note: text(),
    ...audit(),
  },
  (t) => [index('source_parish_idx').on(t.parishId)],
);

// A heading inside a source ("Крещенные в Тешково от 1 июля до 14 декабря 1897 года").
export const sourceSection = snakeCase.table(
  'source_section',
  {
    id: integer().primaryKey(),
    sourceId: integer()
      .notNull()
      .references(() => source.id, { onDelete: 'cascade' }),
    title: text().notNull(),
  },
  (t) => [index('source_section_source_idx').on(t.sourceId)],
);

export { recordStatuses };

// One entry in a source: a baptism, a wedding, a death, or one household or
// farm in a list. Kind-specific columns live in the record_* tables below
// (one row per record, sharing its id).
export const record = snakeCase.table(
  'record',
  {
    id: integer().primaryKey(),
    sourceId: integer()
      .notNull()
      .references(() => source.id, { onDelete: 'restrict' }),
    sectionId: integer().references(() => sourceSection.id, { onDelete: 'set null' }),
    page: text(), // as numbered in the source: "221об"
    status: text({ enum: recordStatuses }).default('ok').notNull(),
    date: text(), // baptism, wedding or death date; the list's date for lists
    // For the map's timeline: grouping by place and year needs no date parsing.
    year: integer().generatedAlwaysAs(sql`cast(substr(date, 1, 4) as integer)`),
    // Where the people of the entry lived (the village column), not where
    // the ceremony took place (see record_baptism.location).
    placeText: text(),
    placeId: integer().references(() => place.id, { onDelete: 'set null' }),
    note: text(),
    raw: text({ mode: 'json' }).$type<Record<string, string>>(), // the original row, column by column
    // The entry's names and places in one lowercase string (ё as е), for
    // searching: SQLite's LIKE and lower() fold case only for ASCII, so
    // Cyrillic is folded when the record is written. See ~/lib/search-text.
    searchText: text(),
    ...audit(),
  },
  (t) => [
    index('record_source_idx').on(t.sourceId),
    index('record_place_year_idx').on(t.placeId, t.year),
    index('record_date_idx').on(t.date),
  ],
);

export { baptismLocations };

export const recordBaptism = snakeCase.table(
  'record_baptism',
  {
    recordId: integer()
      .primaryKey()
      .references(() => record.id, { onDelete: 'cascade' }),
    birthDate: text(),
    officiantText: text(), // "В пасторате пастор Вехнияйнен"
    officiantId: integer().references(() => clergy.id, { onDelete: 'set null' }),
    location: text({ enum: baptismLocations }),
    locationPlaceId: integer().references(() => place.id, { onDelete: 'set null' }),
    // Emergency baptism by a layperson (a `lay_baptizer` persona), later
    // confirmed by the officiant.
    emergencyDate: text(),
    multipleBirth: integer(), // 2 twins, 3 triplets
    illegitimate: integer({ mode: 'boolean' }).default(false).notNull(),
    stillborn: integer({ mode: 'boolean' }).default(false).notNull(),
  },
  (t) => [index('record_baptism_birth_date_idx').on(t.birthDate)],
);

export const recordDeath = snakeCase.table('record_death', {
  recordId: integer()
    .primaryKey()
    .references(() => record.id, { onDelete: 'cascade' }),
  burialDate: text(),
  causeText: text(),
  causeTermId: integer().references(() => term.id, { onDelete: 'set null' }),
});

// A household (№ двора) or a farm in a taxpayer list (№ хозяйства).
export const recordHolding = snakeCase.table('record_holding', {
  recordId: integer()
    .primaryKey()
    .references(() => record.id, { onDelete: 'cascade' }),
  holdingNo: text(),
  estateText: text(), // поместье
  estatePlaceId: integer().references(() => place.id, { onDelete: 'set null' }),
  tenantText: text(), // арендатор
});

// --- People ---------------------------------------------------------------------

export { sexes };

// A researched identity: the personas an admin decided are the same person.
export const person = snakeCase.table('person', {
  id: integer().primaryKey(),
  sex: text({ enum: sexes }),
  nameRu: text(),
  nameFi: text(),
  birthDate: text(),
  deathDate: text(),
  note: text(),
  ...audit(),
});

export const personaRoles = [
  'child',
  'father',
  'mother',
  'lay_baptizer',
  'groom',
  'bride',
  'deceased',
  'member', // of a household; `relationText` says how (отец, сын…)
  'taxpayer',
] as const;

// A person as one record mentions them. Names are kept whole as written
// (`nameRu`, `nameFi`) and split into parts for search and display.
export const persona = snakeCase.table(
  'persona',
  {
    id: integer().primaryKey(),
    recordId: integer()
      .notNull()
      .references(() => record.id, { onDelete: 'cascade' }),
    role: text({ enum: personaRoles }).notNull(),
    sex: text({ enum: sexes }),

    nameRu: text(),
    givenRu: text(),
    patronymicRu: text(),
    surnameRu: text(),
    maidenRu: text(),
    nameFi: text(),
    givenFi: text(),
    patronymicFi: text(),
    surnameFi: text(),
    maidenFi: text(),

    ageText: text(),
    birthDate: text(),
    deathDate: text(),
    birthplaceText: text(),
    birthplaceId: integer().references(() => place.id, { onDelete: 'set null' }),
    relationText: text(),
    relationTermId: integer().references(() => term.id, { onDelete: 'set null' }),
    rankText: text(),
    rankTermId: integer().references(() => term.id, { onDelete: 'set null' }),
    civilStatusText: text(),
    civilStatusTermId: integer().references(() => term.id, { onDelete: 'set null' }),
    familyNo: text(), // № семьи within a household
    hasWife: integer({ mode: 'boolean' }), // taxpayer lists
    origin: text(), // "эстонец, Везенбергский уезд"
    note: text(),
    noteOriginal: text(),

    personId: integer().references(() => person.id, { onDelete: 'set null' }),
    ...audit(),
  },
  (t) => [
    index('persona_record_idx').on(t.recordId),
    index('persona_person_idx').on(t.personId),
    index('persona_surname_ru_idx').on(t.surnameRu),
    index('persona_surname_fi_idx').on(t.surnameFi),
    index('persona_maiden_ru_idx').on(t.maidenRu),
  ],
);

// --- History --------------------------------------------------------------------

export const changeActions = ['create', 'update', 'delete'] as const;

// Every admin edit, with the row before and after, so changes can be traced
// and undone.
export const changeLog = snakeCase.table(
  'change_log',
  {
    id: integer().primaryKey(),
    at: integer({ mode: 'timestamp_ms' }).default(now).notNull(),
    userId: text().references(() => user.id, { onDelete: 'set null' }),
    entity: text().notNull(), // table name
    entityId: integer().notNull(),
    action: text({ enum: changeActions }).notNull(),
    before: text({ mode: 'json' }),
    after: text({ mode: 'json' }),
  },
  (t) => [
    index('change_log_entity_idx').on(t.entity, t.entityId),
    index('change_log_at_idx').on(t.at),
  ],
);
